function same(a,b){if(a.length!==b.length)return false;let diff=0;for(let i=0;i<a.length;i++)diff|=a.charCodeAt(i)^b.charCodeAt(i);return diff===0;}
function sessionToken(req){return(req.headers.get('cookie')||'').split(';').map(v=>v.trim()).find(v=>v.startsWith('__Host-labour_session='))?.slice(22)||'';}
function sessionResponse(body,token,maxAge=28800){return Response.json(body,{headers:{'Cache-Control':'no-store','Set-Cookie':'__Host-labour_session='+token+'; Path=/; Secure; HttpOnly; SameSite=None; Partitioned; Max-Age='+maxAge}});}
async function identity(req,d){const token=sessionToken(req);if(!/^[a-f0-9]{64}$/.test(token))fail('Enter your username and password.',401);const row=await d.prepare('SELECT a.username,a.role FROM sessions s JOIN accounts a ON a.username=s.username WHERE s.token_hash=? AND s.expires>?').bind(await tokenHash(token),Date.now()).first();if(!row||!['admin','supervisor','viewer'].includes(row.role))fail('Your session has ended. Please sign in again.',401);return{username:row.username,role:row.role,isOwner:row.username==='Dream@0186'};}
async function login(req,d){const b=await req.json();if(typeof b.username!=='string'||typeof b.password!=='string'||b.username.length>80||b.password.length>200)fail('Invalid username or password.',401);const username=b.username.trim(),now=Date.now(),key=await tokenHash(username+'|'+(req.headers.get('cf-connecting-ip')||''));
const attempt=await d.prepare('SELECT * FROM login_attempts WHERE key=?').bind(key).first();if(attempt&&attempt.expires>now&&attempt.count>=5)fail('Too many login attempts. Try again in 15 minutes.',429);
await d.prepare('INSERT INTO login_attempts(key,count,expires) VALUES(?,1,?) ON CONFLICT(key) DO UPDATE SET count=CASE WHEN expires>? THEN count+1 ELSE 1 END,expires=CASE WHEN expires>? THEN expires ELSE excluded.expires END').bind(key,now+900000,now,now).run();
await d.batch(INITIAL_ACCOUNTS.map(a=>d.prepare('INSERT INTO accounts(username,password_hash,salt,role) VALUES(?,?,?,?) ON CONFLICT(username) DO NOTHING').bind(a.username,a.hash,a.salt,a.role)));
const account=await d.prepare('SELECT * FROM accounts WHERE username=?').bind(username).first();const hash=await passwordHash(b.password,account?.salt||INITIAL_ACCOUNTS[0].salt);if(!account||!same(hash,account.password_hash)||!['admin','supervisor','viewer'].includes(account.role))fail('Invalid username or password.',401);
const token=hex(crypto.getRandomValues(new Uint8Array(32)));await d.batch([d.prepare('DELETE FROM login_attempts WHERE key=? OR expires<?').bind(key,now),d.prepare('DELETE FROM sessions WHERE expires<?').bind(now),d.prepare('INSERT INTO sessions(token_hash,username,expires) VALUES(?,?,?)').bind(await tokenHash(token),username,now+28800000)]);return sessionResponse({ok:true},token);}
