const PWA_MANIFEST=JSON.stringify({name:'Dream Construction Attendance',short_name:'Dream Construction',description:'Labour attendance, work sites, overtime and salary records.',start_url:'/',scope:'/',display:'standalone',orientation:'portrait-primary',background_color:'#eaf8ff',theme_color:'#092f67',icons:[{src:'/app-icon.svg?v=company-2',sizes:'any',type:'image/svg+xml',purpose:'any maskable'}]});
const SERVICE_WORKER="const CACHE='dream-construction-v2';const APP=['/','/manifest.webmanifest','/logo.png?v=company-2','/app-icon.svg?v=company-2'];self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(APP)));self.skipWaiting();});self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key!==CACHE).map(key=>caches.delete(key)))));self.clients.claim();});self.addEventListener('fetch',event=>{const request=event.request,url=new URL(request.url);if(request.method!=='GET'||url.pathname.startsWith('/api/'))return;if(request.mode==='navigate'){event.respondWith(fetch(request).then(response=>{const copy=response.clone();caches.open(CACHE).then(cache=>cache.put('/',copy));return response;}).catch(()=>caches.match('/')));return;}event.respondWith(caches.match(request).then(cached=>cached||fetch(request).then(response=>{if(response.ok&&url.origin===location.origin){const copy=response.clone();caches.open(CACHE).then(cache=>cache.put(request,copy));}return response;})));});";
